/** Original reading drafts. Authoring levels are hypotheses, not calibrated scores. */
export const readingItems = [];
export const readingStimuli = [];
const bi = (en, ru) => ({ en, ru });
const constructs = {
  gist: bi('Identifying the central message or purpose', 'Определение основной мысли или цели текста'),
  detail: bi('Locating and interpreting an explicit detail', 'Поиск и понимание явной детали'),
  inference: bi('Drawing a locally supported inference', 'Вывод, подтверждённый данным текстом'),
  reference: bi('Resolving what an expression refers to', 'Определение того, к чему относится выражение'),
  attitude: bi('Interpreting an attitude with its qualifications', 'Понимание отношения автора с учётом оговорок'),
  organisation: bi('Understanding the role or relationship of text parts', 'Понимание роли и связи частей текста'),
};
const broadTags = { gist: 'gist', detail: 'explicit-detail', inference: 'inference', reference: 'reference', attitude: 'writer-attitude', organisation: 'organisation' };
// Every passage, question, option and explanation below is individually written.
// This helper only attaches common schema fields; it generates no question text.
function add(id, level, title, genre, topic, text, questions) {
  readingStimuli.push({ id, domain: 'reading', authoringLevel: level, targetLevel: level,
    targetLevelStatus: 'author_hypothesis', title, type: genre, topic, text,
    source: 'original', clusterId: id, validationStatus: 'draft_uncalibrated' });
  questions.forEach((q, index) => {
    const [skill, prompt, choices, correctIndex, explanation, answerEvidence, reasons, extraTags = []] = q;
    readingItems.push({ id: `${id}-q${index + 1}`, domain: 'reading', stimulusId: id,
      targetLevel: level, targetLevelStatus: 'author_hypothesis', source: 'original',
      validationStatus: 'draft_uncalibrated', construct: constructs[skill], prompt,
      choices, correctIndex, explanation: bi(...explanation), answerEvidence,
      distractorRationales: reasons.map(([choiceIndex, en, ru]) => ({ choiceIndex, en, ru })),
      scopeLimits: bi('Evidence from one question in a five-question text cluster; neither a standalone CEFR classification nor five independent confirmations.', 'Свидетельство по одному вопросу в блоке из пяти вопросов к тексту; не отдельная классификация CEFR и не пять независимых подтверждений.'),
      topic, tags: [broadTags[skill], ...extraTags] });
  });
}

