// Stable option shuffling removes authoring-position patterns. It is not test security.
// Item text, keyed meaning and every distractor rationale are preserved together.
function optionSeed(value) {
  let seed = 2166136261;
  for (const char of value) seed = Math.imul(seed ^ char.charCodeAt(0), 16777619);
  return seed >>> 0;
}
for (const item of readingItems) {
  let seed = optionSeed(item.id);
  const random = () => {
    seed = (seed + 0x6D2B79F5) >>> 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t ^= t + Math.imul(t ^ (t >>> 7), 61 | t);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  const order = [0, 1, 2, 3];
  for (let i = 3; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [order[i], order[j]] = [order[j], order[i]];
  }
  const oldChoices = item.choices;
  item.choices = order.map(index => oldChoices[index]);
  item.correctIndex = order.indexOf(item.correctIndex);
  item.distractorRationales = item.distractorRationales.map(rationale => ({
    ...rationale, choiceIndex: order.indexOf(rationale.choiceIndex),
  })).sort((a, b) => a.choiceIndex - b.choiceIndex);
}

export const readingMetadata = {
  version: `large-reading-draft-1-${readingItems.length}`,
  status: 'original_uncalibrated_drafts',
  plannedStimulusCount: 48, plannedQuestionCount: 240,
  stimulusCount: readingStimuli.length, questionCount: readingItems.length,
  complete: readingItems.length === 240,
  intendedCounts: { A1: 50, A2: 50, B1: 50, B2: 50, C1: 40 },
  levelPolicy: 'Author hypotheses only; no validated CEFR difficulty, cut scores or sublevels.',
  clusterPolicy: 'Five responses per passage are one stimulus cluster, not five independent confirmations.',
  securityPolicy: 'This browser-delivered draft bank is inspectable; it is not a secure high-stakes examination.',
};
export default { readingItems, readingStimuli, readingMetadata };
